import { createOrchestrator } from './core/orchestration.mjs';

// This module is SDK-free: unit tests import it without the host package.
// The committed package entry (dist/extension.js, generated by
// scripts/build.mjs) binds the host's CustomEditor with a STATIC import, so
// the senpi loader aliases @earendil-works/pi-coding-agent while it transforms
// the extension graph. A dynamic import from a jiti-compiled module stays a
// native import and cannot resolve the aliased package.
export function createPrimaryAgentsExtension(options = {}) {
  return function primaryAgentsExtension(pi) {
    createOrchestrator(pi, options);
  };
}

// Every handler is registered here, at factory time. Handlers stay inert until
// the interactive TUI main session starts (`session_start` -> isPrimaryMain).
export default function primaryAgentsExtension(pi) {
  createOrchestrator(pi);
}
